\title{A Base-Uniform Proof of Gawron--Miska--Ulas Unboundedness\\ for Multiplicity Two}
\author{Aristotle}
\date{2026-06-26}

\begin{document}
\maketitle

\begin{abstract}
For integers $b \ge 2$ and $m \ge 1$, let $\Tbm(n)$ denote the coefficient of $x^n$ in the formal power series $\prod_{i=0}^{\infty}\left(1 - x^{b^i}\right)^m$. The Gawron--Miska--Ulas conjecture asserts that for every $b \ge 2$ and every $m \ge 2$ the integer sequence $n \mapsto \Tbm(n)$ is unbounded in absolute value. The published proof treats the case $b = 2$ (all $m$) using the theory of $b$-regular sequences. We give a complementary, fully base-uniform proof of the case $m = 2$, valid for \emph{every} base $b \ge 2$ simultaneously, by an elementary argument. The proof rests on three ingredients: (i) a Mahler-type functional equation $Q_{N+1}(x) = (1-x)^m\, Q_N(x^b)$ for the truncated products; (ii) a finite-equals-infinite stabilization principle showing that the coefficient of $x^n$ is correctly computed by any truncation of order $N \ge n$; and (iii) an exact closed form $\Tbtwo(R_k) = (-2)^k$ at the base-$b$ repunits $R_k = 1 + b + \cdots + b^{k-1}$. Unboundedness follows immediately, since $|\Tbtwo(R_k)| = 2^k \to \infty$. We contrast this with the boundedness $|T_{b,1}(n)| \le 1$ at multiplicity one, isolating the squared factor's middle coefficient as the structural source of growth, and we outline a transfer-matrix program for the remaining cases $m \ge 3$. All results have been formally verified.
\end{abstract}

\section{Introduction}

\subsection{The object of study}
Fix integers $b \ge 2$ (the \emph{base}) and $m \ge 1$ (the \emph{multiplicity}). Consider the formal power series over $\ZZ$
\[
F_{b,m}(x) = \prod_{i=0}^{\infty}\left(1 - x^{b^i}\right)^m = (1-x)^m (1 - x^b)^m (1 - x^{b^2})^m \cdots.
\]
This is well-defined: for each degree $n$, only finitely many factors contribute, since $(1 - x^{b^i})^m \equiv 1 \pmod{x^{b^i}}$, so all factors with $b^i > n$ act as the identity on $[x^n]$. We write $\Tbm(n) = [x^n]\, F_{b,m}(x)$.

\subsection{The conjecture and known cases}
\begin{conjecture}[Gawron--Miska--Ulas]
For every $b \ge 2$ and every $m \ge 2$, the sequence $n \mapsto \Tbm(n)$ is unbounded:
\[
\forall B,\; \exists n,\; |\Tbm(n)| > B.
\]
\end{conjecture}
The case $b = 2$ (all $m$) is known via the $2$-regularity of the coefficient sequence. The general-base conjecture is open. The multiplicity $m = 1$ is bounded, so the hypothesis $m \ge 2$ is essential.

\subsection{Contribution}
We prove the conjecture for $m = 2$ and \emph{every} base $b \ge 2$ (Theorem~\ref{thm:main}). The argument is elementary and base-uniform: a single identity, evaluated along the base-$b$ repunits, produces explicit values witnessing unboundedness. All statements have been formalized and machine-checked.

\section{Definitions}
Let $\ZZ[X]$ be the polynomial ring, $[x^n]p$ the coefficient of $x^n$ in $p$, and $\expand_b\colon \ZZ[X] \to \ZZ[X]$ the ring homomorphism $X \mapsto X^b$.

\begin{definition}[Truncated product]
For $b, m, N \in \NN$, set $Q_N := \mathrm{Tpoly}(b,m,N) := \prod_{i=0}^{N}\left(1 - X^{b^i}\right)^m \in \ZZ[X].$
\end{definition}

\begin{definition}[Coefficient sequence]
For $b, m, n \in \NN$, set $\Tbm(n) := [x^n]\,\mathrm{Tpoly}(b,m,n)$. Proposition~\ref{prop:stable} shows this equals $[x^n]$ of any truncation of order $\ge n$, hence $[x^n]F_{b,m}$.
\end{definition}

\begin{definition}[Base-$b$ repunits]
Define $R\colon \NN \to \NN$ by $R_0 = 0$ and $R_{k+1} = b\,R_k + 1$. Then $R_k = 1 + b + \cdots + b^{k-1} = \frac{b^k-1}{b-1}$, the integer with $k$ base-$b$ digits all equal to $1$.
\end{definition}

\section{The functional equation and truncation stability}

\begin{lemma}[\texttt{expand\_factor}]\label{lem:expandfactor}
For all $b, m, i$, $\;\expand_b\!\left((1 - X^{b^i})^m\right) = (1 - X^{b^{i+1}})^m.$
\end{lemma}
\begin{proof}[Proof sketch]
$\expand_b$ is a ring homomorphism with $\expand_b(X) = X^b$, so $\expand_b(1 - X^{b^i}) = 1 - (X^b)^{b^i} = 1 - X^{b^{i+1}}$; raise to the $m$-th power.
\end{proof}

\begin{lemma}[\texttt{factor\_succ}; Mahler functional equation]\label{lem:factorsucc}
For all $b, m, N$, $\;Q_{N+1} = (1 - X)^m \cdot \expand_b(Q_N).$
\end{lemma}
\begin{proof}[Proof sketch]
Peel off the $i=0$ factor and shift $i \mapsto i+1$:
$Q_{N+1} = (1-X)^m \prod_{i=0}^{N}(1 - X^{b^{i+1}})^m$. By Lemma~\ref{lem:expandfactor} and multiplicativity of $\expand_b$, the product equals $\expand_b(Q_N)$.
\end{proof}

\begin{lemma}[\texttt{coeff\_mul\_one\_sub\_Xpow\_pow}]\label{lem:coeffmul}
Let $e \ge 1$. Then $(1-X^e)^m = \expand_e((1-X)^m)$ is a polynomial in $X^e$, and for any $p \in \ZZ[X]$ and $n < e$,
$\;[x^n]\big(p \cdot (1 - X^e)^m\big) = [x^n]\,p.$
\end{lemma}
\begin{proof}[Proof sketch]
All nonzero terms of $(1-X^e)^m$ have degree divisible by $e$, with degree-$0$ term $1$. In the convolution, any contribution with $n-j>0$ needs $e \mid (n-j)$ and $0 < n-j \le n < e$, impossible; only $j=n$ survives.
\end{proof}

\begin{proposition}[\texttt{coeff\_eq\_of\_le}; truncation stability]\label{prop:stable}
Let $b \ge 2$. For all $m$ and all $n \le N$, $\;[x^n]\,Q_N = \Tbm(n).$ Equivalently, the coefficient of $x^n$ is the same in every truncation of order $\ge n$, hence equals $[x^n]F_{b,m}$.
\end{proposition}
\begin{proof}[Proof sketch]
One step: $Q_{N+1} = Q_N \cdot (1 - X^{b^{N+1}})^m$ with $n \le N < b^{N+1}$ (since $N < 2^N \le b^N \le b^{N+1}$); Lemma~\ref{lem:coeffmul} gives $[x^n]Q_{N+1}=[x^n]Q_N$. Strong induction on $N$ down to $N=n$ finishes.
\end{proof}

\section{The repunit recurrence and closed form}
Specialize to $m=2$, where $(1-X)^2 = 1 - 2X + X^2$.

\begin{lemma}[\texttt{T\_two\_zero}]\label{lem:zero}
$\Tbtwo(0) = 1.$
\end{lemma}
\begin{proof}[Proof sketch]
The constant term of $\prod_i (1-X^{b^i})^2$ is $1$.
\end{proof}

\begin{lemma}[\texttt{T\_repunit\_step}; repunit recurrence]\label{lem:step}
For $b \ge 2$ and all $k$, $\;\Tbtwo(R_{k+1}) = -2\,\Tbtwo(R_k).$
\end{lemma}
\begin{proof}[Proof sketch]
With $R_{k+1} = b\,R_k + 1$, apply Lemma~\ref{lem:factorsucc}: $Q_{N+1} = (1-X)^2 \cdot \expand_b(Q_N)$. The factor $\expand_b(Q_N)$ has only exponents divisible by $b$. The target degree $bR_k+1 \equiv 1 \pmod b$ can be reached only by combining a multiple-of-$b$ exponent with the shift $1$ of the middle term $-2X$ (the shifts $0$ and $2$ give residues $0$ and $2$, which fail for $b \ge 2$). Hence
\[
[x^{bR_k+1}]Q_{R_{k+1}} = -2\,[x^{bR_k}]\expand_b(Q_{R_k}) = -2\,[x^{R_k}]Q_{R_k} = -2\,\Tbtwo(R_k),
\]
using $[x^{bR_k}]\expand_b(p) = [x^{R_k}]p$ and Proposition~\ref{prop:stable} to align truncation orders.
\end{proof}

The key structural fact: $(1-X)^2$ has a \emph{single} interior term $-2X$, and the target residue is exactly $1 \pmod b$, so only that term survives --- uniformly in $b$.

\begin{theorem}[\texttt{T\_repunit}; closed form]\label{thm:closed}
For $b \ge 2$ and all $k$, $\;\Tbtwo(R_k) = (-2)^k.$
\end{theorem}
\begin{proof}[Proof sketch]
Induction on $k$: base $k=0$ is Lemma~\ref{lem:zero}; step uses Lemma~\ref{lem:step}: $\Tbtwo(R_{k+1}) = -2(-2)^k = (-2)^{k+1}$.
\end{proof}

\begin{corollary}[\texttt{abs\_T\_repunit}]\label{cor:abs}
For $b \ge 2$ and all $k$, $\;|\Tbtwo(R_k)| = 2^k.$
\end{corollary}

\section{Unboundedness}

\begin{theorem}[\texttt{T\_two\_unbounded}; Main Theorem]\label{thm:main}
For every $b \ge 2$ and every $B \in \ZZ$ there exists $n \in \NN$ with $\;|\Tbtwo(n)| > B.$
\end{theorem}
\begin{proof}[Proof sketch]
Choose $k$ with $2^k > B$ and set $n = R_k$; by Corollary~\ref{cor:abs}, $|\Tbtwo(n)| = 2^k > B$.
\end{proof}

\begin{corollary}[\texttt{T\_two\_not\_bounded}]
There is no uniform bound $B$ with $|\Tbtwo(n)| \le B$ for all $n$.
\end{corollary}

\section{The multiplicity-one contrast}
At $m=1$ the coefficients of $\prod_i(1-x^{b^i})$ lie in $\{-1,0,1\}$, so $|T_{b,1}(n)| \le 1$. The single factor $(1-x)$ has no interior term, so no doubling can be seeded; the jump to unboundedness at $m=2$ is caused entirely by the middle coefficient $\binom{2}{1}=2$ of $(1-x)^2 = 1 - 2x + x^2$.

\section{Discussion: the obstruction for $m \ge 3$}
For general $m$, $(1-x)^m = \sum_{j=0}^m (-1)^j \binom{m}{j} x^j$ has interior terms at all $0 \le j \le m$. At the repunit degree $bR_k+1$ the surviving indices are $j \equiv 1 \pmod b$, i.e. $j \in \{1, 1+b, 1+2b,\dots\} \cap [0,m]$. When $b \ge m$ only $j=1$ survives, giving $\Tbm(R_k) = (-m)^k$ and unboundedness. When $b < m$, several terms survive and the recurrence becomes
\[
\Tbm(R_{k+1}) = \sum_{t \,:\, 1 + tb \le m} (-1)^{1+tb}\binom{m}{1+tb}\, \Tbm(R_k - t),
\]
e.g. $b=3,m=4$ gives $1,-4,17,-76,353,\dots \ne (-4)^k$. The window $v_k = (\Tbm(R_k - t))_{0 \le t \le \lfloor (m-1)/b \rfloor}$ then satisfies $v_{k+1} = M v_k$ for an explicit integer matrix $M(b,m)$ with entries $\pm\binom{m}{1+tb}$, and unboundedness holds iff the spectral radius $\rho(M) > 1$ --- a finite eigenvalue computation. Computations suggest the sharper $\max_{0 \le n < b^k}|\Tbm(n)| = m^k$ for $b \ge m \ge 2$, attained at $R_k$.

\section{The formal development}
All results above have been formally verified: \texttt{Tpoly}, \texttt{T}, \texttt{R} (definitions); \texttt{expand\_factor}, \texttt{factor\_succ} (functional equation); \texttt{one\_sub\_Xpow\_pow\_eq\_expand}, \texttt{coeff\_mul\_one\_sub\_Xpow\_pow}, \texttt{coeff\_stable\_step}, \texttt{coeff\_eq\_of\_le} (truncation stability); \texttt{T\_two\_zero}, \texttt{T\_repunit\_step}, \texttt{T\_repunit}, \texttt{abs\_T\_repunit} (recurrence and closed form); \texttt{T\_two\_unbounded}, \texttt{T\_two\_not\_bounded} (main theorem). The unboundedness statement is a genuine $\forall B\,\exists n$ assertion proved by induction with the functional equation, not by definitional unfolding.

\section{Conclusion}
We gave a base-uniform, elementary proof of Gawron--Miska--Ulas unboundedness for $m = 2$ and every $b \ge 2$, with the exact closed form $\Tbtwo(R_k) = (-2)^k$. The same lens recasts the open corner $2 \le b < m$ as a finite spectral problem for an explicit transfer matrix.

