\bibitem{GMU} A. Gawron, P. Miska, M. Ulas, on coefficient sequences of products $\prod_i (1 - x^{b^i})^m$ and their boundedness (base $b=2$).
\bibitem{Mahler} K. Mahler, on functional equations $F(x) = a(x)F(x^b)$ and regular/automatic sequences.
\end{thebibliography}

