function REPUNIT_VALUE(b, m, k):
    if b >= m:
        return (-m)^k                      # single-ratio collapse
    return DIRECT_EXTRACT(b, m, k)

function SURVIVING_COEFFS(b, m):
    coeffs <- []
    t <- 0
    while 1 + t*b <= m:
        j <- 1 + t*b
        coeffs.append( (-1)^j * C(m, j) )
        t <- t + 1
    return coeffs

function TRANSFER_MATRIX(b, m):
    T <- floor((m-1)/b);  size <- T + 1
    M <- zero matrix of shape (size, size)
    for (t, c) in enumerate(SURVIVING_COEFFS(b, m)):
        if t < size: M[0][t] <- c          # recurrence row
    for r in 1 .. size-1: M[r][r-1] <- 1    # shift rows
    return M

function DIRECT_EXTRACT(b, m, k):
    n <- R_k                                # n = 1 + b + ... + b^{k-1}
    P <- [1]                                # polynomial, degree-indexed
    exp <- 1
    while exp <= n:
        F <- coeffs of (1 - x^exp)^m up to degree n
        P <- truncate( P * F, n )
        exp <- exp * b
    return P[n]
